(function () {
    var canvas = document.getElementById("fireworks");
    if (!canvas) return;

    var ctx = canvas.getContext("2d");
    var colors = ["#ff324a", "#31ffa6", "#206eff", "#ffff99"];
    var bursts = [];
    var running = false;
    var dpr = 1;

    function viewport() {
        var vv = window.visualViewport;
        if (vv) {
            return {
                width: vv.width,
                height: vv.height,
                left: vv.offsetLeft,
                top: vv.offsetTop
            };
        }
        return {
            width: document.documentElement.clientWidth,
            height: document.documentElement.clientHeight,
            left: 0,
            top: 0
        };
    }

    function resize() {
        var vp = viewport();
        dpr = window.devicePixelRatio || 1;
        canvas.style.position = "fixed";
        canvas.style.left = vp.left + "px";
        canvas.style.top = vp.top + "px";
        canvas.style.right = "auto";
        canvas.style.bottom = "auto";
        canvas.style.width = vp.width + "px";
        canvas.style.height = vp.height + "px";
        var width = Math.max(1, Math.round(vp.width * dpr));
        var height = Math.max(1, Math.round(vp.height * dpr));
        if (canvas.width !== width || canvas.height !== height) {
            canvas.width = width;
            canvas.height = height;
        }
    }

    function clearCanvas() {
        ctx.setTransform(1, 0, 0, 1, 0, 0);
        ctx.globalAlpha = 1;
        ctx.clearRect(0, 0, canvas.width, canvas.height);
    }

    function pointFromEvent(event) {
        var rect = canvas.getBoundingClientRect();
        if (!rect.width || !rect.height) return null;
        var x = event.clientX - rect.left;
        var y = event.clientY - rect.top;
        if (x < 0 || y < 0 || x > rect.width || y > rect.height) return null;
        return {
            x: x * (canvas.width / dpr) / rect.width,
            y: y * (canvas.height / dpr) / rect.height
        };
    }

    function spawn(x, y) {
        var particles = [];
        var count = 16;
        for (var i = 0; i < count; i++) {
            var angle = (Math.PI * 2 * i) / count + (Math.random() - 0.5) * 0.4;
            var speed = 2.4 + Math.random() * 4.2;
            particles.push({
                x: x,
                y: y,
                vx: Math.cos(angle) * speed,
                vy: Math.sin(angle) * speed,
                radius: 2.2 + Math.random() * 2.2,
                color: colors[(Math.random() * colors.length) | 0],
                life: 1,
                decay: 0.018 + Math.random() * 0.012
            });
        }
        bursts.push({ particles: particles });
        if (!running) {
            running = true;
            requestAnimationFrame(frame);
        }
    }

    function frame() {
        clearCanvas();
        if (!bursts.length) {
            running = false;
            return;
        }

        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
        for (var i = bursts.length - 1; i >= 0; i--) {
            var particles = bursts[i].particles;
            var alive = false;
            for (var j = 0; j < particles.length; j++) {
                var p = particles[j];
                p.life -= p.decay;
                if (p.life <= 0) continue;
                alive = true;
                p.x += p.vx;
                p.y += p.vy;
                p.vx *= 0.97;
                p.vy *= 0.97;
                var radius = p.radius * p.life;
                if (radius <= 0) continue;
                ctx.globalAlpha = Math.max(p.life, 0);
                ctx.fillStyle = p.color;
                ctx.beginPath();
                ctx.arc(p.x, p.y, radius, 0, Math.PI * 2);
                ctx.fill();
            }
            if (!alive) bursts.splice(i, 1);
        }
        ctx.globalAlpha = 1;

        if (bursts.length) {
            requestAnimationFrame(frame);
        } else {
            clearCanvas();
            running = false;
        }
    }

    function onViewportChange() {
        resize();
        if (!running) clearCanvas();
    }

    resize();
    window.addEventListener("resize", onViewportChange);
    if (window.visualViewport) {
        window.visualViewport.addEventListener("resize", onViewportChange);
        window.visualViewport.addEventListener("scroll", onViewportChange);
    }

    document.addEventListener("mousedown", function (event) {
        if (event.button !== 0) return;
        var target = event.target;
        if (target && target.closest && target.closest("a, button, input, textarea, select, label, summary")) return;
        resize();
        var point = pointFromEvent(event);
        if (!point) return;
        spawn(point.x, point.y);
    });
})();
